/* 인터페이스 입고내역 */
	UPDATE IF_GRDT
	SET PO_NO  = #{PO_NO}
	  , PO_SEQ = #{PO_SEQ}
	WHERE 1=1
	AND BUYER         = #{st_buyer}
	AND LEGACY_GR_NO  = NVL(#{st_legacy_gr_no},' ')
	AND LEGACY_GR_SEQ = NVL(#{st_legacy_gr_seq},' ')
	AND LEGACY_PO_NO  = NVL(#{st_legacy_po_no},' ')
	AND LEGACY_PO_SEQ = NVL(#{st_legacy_po_seq},' ')
